using System;using System.IO;using System.Collections.Generic;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Web.Script.Serialization;
public partial class TV {
 void BuildCommunityLinks(DockPanel header){var icons=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(Root+"brand-icons.json"));var links=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(10,0,20,0),VerticalAlignment=VerticalAlignment.Center};DockPanel.SetDock(links,Dock.Right);header.Children.Add(links);SocialIcon(links,icons["youtube"],"#FF0033","YouTube · @xiazheteng8","https://www.youtube.com/@xiazheteng8");SocialIcon(links,icons["github"],"#24292F","GitHub · @xiazheteng8","https://github.com/xiazheteng8");SocialIcon(links,icons["telegram"],"#26A5E4","Telegram · @xiazheteng8","https://t.me/xiazheteng8");}
 void SocialIcon(Panel panel,string geometry,string color,string tooltip,string url){var path=new System.Windows.Shapes.Path{Data=Geometry.Parse(geometry),Fill=Color(color),Width=21,Height=21,Stretch=Stretch.Uniform};var button=new Button{Content=path,ToolTip=tooltip,Padding=new Thickness(10),Margin=new Thickness(2),Background=Brushes.Transparent,BorderBrush=Brushes.Transparent};button.Click+=(s,e)=>{try{OpenLink(url);}catch(Exception ex){Report(ex.Message);}};System.Windows.Automation.AutomationProperties.SetName(button,tooltip);panel.Children.Add(button);}
 void OpenLink(string url){Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri)||uri.Scheme!="https")throw new Exception("链接必须是有效的 HTTPS 地址");Process.Start(new ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});}
}

